def harden_ssh_config(config_path: str) -> dict:
    desired = {
        "PermitRootLogin": "no",
        "PasswordAuthentication": "no",
        "PubkeyAuthentication": "yes",
        "X11Forwarding": "no",
        "PermitEmptyPasswords": "no",
        "Protocol": "2",
    }

    current = {}
    try:
        with open(config_path, encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                parts = line.split(None, 1)
                if len(parts) == 2:
                    key = parts[0].lower()
                    if key in {k.lower() for k in desired}:
                        current[key] = parts[1].strip()
    except FileNotFoundError:
        return {"error": "config file not found"}

    recommendations = {}
    for key, recommended in desired.items():
        current_value = current.get(key.lower())
        if current_value != recommended:
            recommendations[key] = {
                "current": current_value,
                "recommended": recommended,
            }

    return recommendations
